async function main(ctx) {
  const raw = ctx.input;
  const initialArgs = ctx.lastOutputOf('__initial__') || {};

  // Extract tools array from response
  const hasBody = raw && typeof raw === 'object' && Object.prototype.hasOwnProperty.call(raw, 'body');
  const payload = hasBody ? raw.body : raw;
  const isObject = payload && typeof payload === 'object';
  const allTools = isObject && Array.isArray(payload.data)
    ? payload.data
    : (Array.isArray(payload) ? payload : []);

  // Strip heavy fields (blueprint, etc.)
  const leanTools = allTools.map((t) => ({
    slug: t && t.slug,
    name: t && t.name,
    description: t && t.description,
    category: t && t.category,
  }));

  // Apply search filter
  const query = (initialArgs.q || '').toLowerCase().trim();
  const filtered = query
    ? leanTools.filter((t) => {
        const searchText = [
          t.slug,
          t.name,
          t.description,
          t.category
        ].filter(Boolean).join(' ').toLowerCase();
        return searchText.includes(query);
      })
    : leanTools;

  // Apply pagination
  const total = filtered.length;
  const limit = Math.min(Math.max(initialArgs.limit || 50, 1), 200);
  const offset = Math.max(initialArgs.offset || 0, 0);
  const paginated = filtered.slice(offset, offset + limit);
  const hasMore = (offset + paginated.length) < total;

  return {
    tools: paginated,
    count: paginated.length,
    total,
    limit,
    offset,
    hasMore
  };
}
